                        edge += 1
                        touches_edge = True
                    elif grid[ny][nx] == 5:
                        wall += 1
                    elif (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            regions.append((cells, wall, edge, touches_edge))

    # The colored areas are edge-touching pockets bounded by at least as
    # many 5s as they have exposed sides. Mark the largest and smallest.
    pockets = [x for x in regions if x[3] and x[1] >= x[2] and x[1] >= 2]
