    large = max(pockets, key=lambda x: len(x[0]))
    if small is large:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for r, c in small[0]:
        out[r][c] = 7
    for r, c in large[0]:
        out[r][c] = 8
    return out
